// Video 03 helpers. Re-uses the Video 02 kit (style_kit + v2kit) and adds:
// - its own timing (timing.json is GENERATED by docs/video03/make_timing.py from the real voice, rule 1.24)
// - a shot runner (Shots) that cuts a chapter at the s1..sN beats, so shot lengths always follow the voice
// - world-to-world carry pans (every chapter has its own world, rule 1.21) with a soft seam
// - new SFX (shrink, scan_beep, stamp) and code-drawn graphics (exact numbers, no brand marks)
import React from 'react';
import {AbsoluteFill, Html5Audio, Img, interpolate, Sequence, staticFile, useCurrentFrame} from 'remotion';
import timing from './timing.json';
import {ExitOut, PaperTexture} from '../video02/fx';
import {FadeLayer, WorldCtx, WorldPick, worldSlack} from '../style/worldpan';
import {CountUp, CrossDissolve, DiagonalWipe, HAND, InkReveal, PopIn, SANS, Scene} from '../style/style_kit';
import {hasFile, INK, Prop} from '../video02/v2kit';

export {hasFile, INK, Prop, PriceTag, Punch, Src, Disclaimer, Watermark, LeoBadge, Person, Phone, StatCard, DashArrow, Char, CoinToken} from '../video02/v2kit';

export const FPS = timing.fps;
export const W = 1920;
export const H = 1080;
export const sec = (s: number) => Math.round(s * FPS);

// ---------- timing ----------
export type ChapterId = 'cold' | 'ch1' | 'ch2' | 'ch3' | 'ch4' | 'ch5' | 'ch6' | 'outro';
export type Chapter = {id: string; title: string; audio: string; pre: number; audioDur: number; post: number; overlapFrames?: number; beats: Record<string, number>};
export const CHAPTERS = timing.chapters as unknown as Chapter[];
export const getChapter = (id: ChapterId): Chapter => {
  const c = CHAPTERS.find((x) => x.id === id);
  if (!c) throw new Error(`video03 timing.json has no chapter "${id}"`);
  return c;
};
export const chapterFrames = (c: Chapter) => sec(c.pre) + sec(c.audioDur) + sec(c.post);
export const beatOf = (c: Chapter) => (key: string): number => {
  const v = c.beats[key];
  if (v === undefined) throw new Error(`video03 timing.json chapter "${c.id}" has no beat "${key}"`);
  return sec(v);
};
/** Number of shots in a chapter (beats s1..sN). */
export const shotCount = (c: Chapter) => Object.keys(c.beats).filter((k) => /^s\d+$/.test(k)).length;

// ---------- audio ----------
export const SFX = {
  pop: 'sfx/pop.wav', whoosh: 'sfx/whoosh.wav', kaching: 'sfx/kaching.wav', ding: 'sfx/ding.wav', boom: 'sfx/boom.wav', notify: 'sfx/notify.wav',
  shrink: 'sfx/shrink.wav', scan_beep: 'sfx/scan_beep.wav', stamp: 'sfx/stamp.wav',
} as const;
/** Existing volumes kept; new ones from 02_assets_sfx_music.md (peaks about -6 dB). */
export const SFX_VOL: Record<keyof typeof SFX, number> = {pop: 0.32, whoosh: 0.3, kaching: 0.5, ding: 0.4, boom: 0.45, notify: 0.4, shrink: 0.35, scan_beep: 0.35, stamp: 0.4};
export type SfxName = keyof typeof SFX;
export const Sfx: React.FC<{name: SfxName; at: number}> = ({name, at}) => {
  const file = SFX[name];
  if (!hasFile(file)) return null;
  return (
    <Sequence from={Math.max(0, at)} durationInFrames={sec(2)} layout="none">
      <Html5Audio src={staticFile(file)} volume={SFX_VOL[name]} />
    </Sequence>
  );
};
export const Voice: React.FC<{c: Chapter}> = ({c}) => {
  if (!hasFile(c.audio)) return null;
  return (
    <Sequence from={sec(c.pre)} layout="none">
      <Html5Audio src={staticFile(c.audio)} />
    </Sequence>
  );
};

// ---------- shots ----------
export type Trans = 'none' | 'ink' | 'wipe' | 'dissolve' | 'swap' | 'join';
export const SWAP = 14;
export const TRANS_FRAMES: Record<Trans, number> = {none: 0, ink: 30, wipe: 22, dissolve: 22, swap: SWAP, join: 30};
export type PanDir = 'l' | 'r';
/** Chapter-join pan length (frames). The next chapter starts this many frames early (timing overlapFrames = 30). */
export const PAN_FRAMES = 30;
/** A join travels a full screen: the old world leaves on one side while the new world arrives from the other. */
const JOIN_DIST = W;
const SEAM = 160;
const easeIO = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const cl = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;

/** Carried object: a PNG (`src`) or any drawn node (`node`). handoff = vanish on landing (the same thing is drawn there). */
export type CarrySpec = {from: [number, number]; to: [number, number]; src?: string; h?: number; node?: React.ReactNode; handoff?: boolean};

/** New chapter's first shot: its world slides in from the side with a soft seam, like one camera moving on to the next place. */
const JoinIn: React.FC<{dir: PanDir; children: React.ReactNode}> = ({dir, children}) => {
  const f = useCurrentFrame();
  const e = easeIO(interpolate(f, [0, PAN_FRAMES], [0, 1], cl));
  const sx = dir === 'r' ? 1 : -1;
  const content = interpolate(f, [PAN_FRAMES * 0.45, PAN_FRAMES], [0, 1], cl);
  const mask = f >= PAN_FRAMES ? undefined : dir === 'r' ? `linear-gradient(to right, transparent 0px, black ${SEAM}px)` : `linear-gradient(to left, transparent 0px, black ${SEAM}px)`;
  return (
    <AbsoluteFill style={{transform: `translateX(${sx * JOIN_DIST * (1 - e)}px)`, WebkitMaskImage: mask, maskImage: mask}}>
      <FadeLayer content={content}>{children}</FadeLayer>
    </AbsoluteFill>
  );
};
/** Last shot of a chapter: world and content move away with the camera; the content fades early. */
const JoinOut: React.FC<{dir: PanDir; start: number; children: React.ReactNode}> = ({dir, start, children}) => {
  const f = useCurrentFrame();
  const t = interpolate(f, [start, start + PAN_FRAMES], [0, 1], cl);
  const sx = dir === 'r' ? 1 : -1;
  return (
    <AbsoluteFill style={{transform: `translateX(${-sx * JOIN_DIST * easeIO(t)}px)`}}>
      <FadeLayer content={interpolate(t, [0.05, 0.45], [1, 0], cl)}>{children}</FadeLayer>
    </AbsoluteFill>
  );
};
/** Same world, same camera: only the content changes (the world layer switches when the old one switches off = same pixels). */
const SwapIn: React.FC<{children: React.ReactNode}> = ({children}) => {
  const f = useCurrentFrame();
  return <FadeLayer world={f >= SWAP ? 1 : 0} content={interpolate(f, [0, SWAP], [0, 1], cl)}>{children}</FadeLayer>;
};
const SwapOut: React.FC<{start: number; children: React.ReactNode}> = ({start, children}) => {
  const f = useCurrentFrame();
  return <FadeLayer world={f >= start + SWAP ? 0 : 1} content={interpolate(f, [start, start + SWAP], [1, 0], cl)}>{children}</FadeLayer>;
};

const CarryFly: React.FC<{c: CarrySpec}> = ({c}) => {
  const f = useCurrentFrame();
  const LAND = PAN_FRAMES, GONE = LAND + 14;
  if (c.handoff ? f >= LAND : f > GONE + 8) return null;
  const pos = (fr: number) => {
    const t = easeIO(Math.min(1, Math.max(0, fr / LAND)));
    return [c.from[0] + (c.to[0] - c.from[0]) * t, c.from[1] + (c.to[1] - c.from[1]) * t - Math.sin(Math.PI * t) * 90, t] as const;
  };
  const [x, y, t] = pos(f);
  const out = c.handoff ? 1 : interpolate(f, [GONE, GONE + 8], [1, 0], cl);
  const rot = c.handoff ? 0 : (1 - t) * -14;
  const body = c.node ?? (c.src ? <Img src={staticFile(c.src)} style={{height: c.h ?? 220, width: 'auto', display: 'block'}} /> : null);
  const ghost = (k: number) => {
    const [gx, gy] = pos(f - k * 2);
    return <div key={k} style={{position: 'absolute', left: gx, top: gy, transform: 'translate(-50%, -50%)', opacity: 0.14 / k}}>{body}</div>;
  };
  return (
    <AbsoluteFill style={{pointerEvents: 'none'}}>
      {f < LAND - 4 && [1, 2].map(ghost)}
      <div style={{position: 'absolute', left: x, top: y, transform: `translate(-50%, -50%) rotate(${rot}deg) scale(${out})`}}>{body}</div>
    </AbsoluteFill>
  );
};

type ShotProps = {from: number; to: number; trans?: Trans; tail?: number; seed?: string; exit?: 'fade' | 'swap' | 'none'; exitPan?: PanDir; pan?: PanDir; carry?: CarrySpec; world: WorldPick; children: React.ReactNode};
/** One shot. It stays on screen through the next shot's transition, so there is never a gap. */
export const Shot: React.FC<ShotProps> = ({from, to, trans = 'none', tail = 34, seed = 's', exit = 'fade', exitPan, pan = 'r', carry, world, children}) => {
  const d = TRANS_FRAMES[trans];
  const body =
    trans === 'ink' ? <InkReveal dur={d} seed={seed}>{children}</InkReveal>
    : trans === 'wipe' ? <DiagonalWipe dur={d}>{children}</DiagonalWipe>
    : trans === 'dissolve' ? <CrossDissolve dur={d}>{children}</CrossDissolve>
    : trans === 'join' ? <JoinIn dir={pan}>{children}</JoinIn>
    : trans === 'swap' ? <SwapIn>{children}</SwapIn>
    : <AbsoluteFill>{children}</AbsoluteFill>;
  const inner = exitPan ? <JoinOut dir={exitPan} start={to - from}>{body}</JoinOut>
    : exit === 'swap' ? <SwapOut start={to - from}>{body}</SwapOut>
    : exit === 'fade' ? <ExitOut start={to - from - 10} dur={16}>{body}</ExitOut>
    : body;
  const dur = exitPan ? to - from + PAN_FRAMES + 1 : Math.max(1, to - from + tail);
  return (
    <Sequence from={from} durationInFrames={dur}>
      <WorldCtx.Provider value={{...world, from}}>{inner}</WorldCtx.Provider>
      <PaperTexture />
      {trans === 'join' && carry && <CarryFly c={carry} />}
    </Sequence>
  );
};

/** One entry of a chapter's shot list. `body(r, dur)`: r('beat') = frame of a beat relative to this shot (never < 0). */
export type ShotDef = {trans?: Trans; seed?: string; pan?: PanDir; carry?: CarrySpec; body: (r: (k: string) => number, dur: number) => React.ReactNode};

/**
 * Runs a chapter's shots: shot k lasts from beat s(k) to s(k+1) (the voice-based cuts from rule 1.24).
 * The world is one per chapter (same pixels across swaps, slow drift <= 8 px/s).
 * exitPan: the chapter ends with a carry pan in that direction (the last shot ends PAN_FRAMES before the chapter end).
 */
export const Shots: React.FC<{b: (k: string) => number; len: number; c: Chapter; src: string; x0: number; drift?: number; exitPan?: PanDir; list: ShotDef[]}> = ({b, len, c, src, x0, drift = 1, exitPan, list}) => {
  const n = shotCount(c);
  if (n !== list.length) throw new Error(`chapter ${c.id}: ${n} shots in timing.json but ${list.length} in code`);
  const slack = worldSlack(src);
  const x1 = Math.min(slack, x0 + (len / FPS) * 8 * drift);
  const world: WorldPick = {src, x0, x1, a: 0, b: len};
  const end = exitPan ? len - PAN_FRAMES : len;
  return (
    <>
      {list.map((s, k) => {
        const from = b(`s${k + 1}`);
        const to = k < n - 1 ? b(`s${k + 2}`) : end;
        const next = list[k + 1];
        const last = k === n - 1;
        const r = (key: string) => Math.max(0, b(key) - from);
        return (
          <Shot key={k} from={from} to={to} trans={s.trans ?? (k === 0 ? 'none' : 'swap')} seed={s.seed ?? `${c.id}${k}`} pan={s.pan} carry={s.carry} world={world}
            exitPan={last ? exitPan : undefined}
            exit={last ? 'none' : (next.trans ?? 'swap') === 'swap' ? 'swap' : 'fade'}
            tail={last ? len - to + 2 : 34}>
            <Scene palette="sunrise" dur={to - from}>{s.body(r, to - from)}</Scene>
          </Shot>
        );
      })}
    </>
  );
};

// ---------- code-drawn graphics (numbers are exact; no brand marks) ----------
const card = (bg = '#FFF8EC'): React.CSSProperties => ({background: bg, border: `7px solid ${INK}`, borderRadius: 28, boxShadow: '0 10px 0 rgba(0,0,0,0.2)', boxSizing: 'border-box'});

/** A prop that pops in and (optionally) shrinks at `shrinkAt` (pair with <Sfx name="shrink" />). */
export const ShrinkProp: React.FC<{name: string; h: number; at?: number; x: number; y: number; shrinkAt?: number; to?: number; flip?: boolean}> = ({name, h, at = 0, x, y, shrinkAt, to = 0.8, flip}) => {
  const f = useCurrentFrame();
  const s = shrinkAt === undefined ? 1 : interpolate(f, [shrinkAt, shrinkAt + 8, shrinkAt + 12], [1, to * 0.96, to], cl);
  return (
    <PopIn at={at} style={{left: x, top: y}}>
      <div style={{transform: `scale(${s})`, transformOrigin: '50% 100%'}}><Prop name={name} h={h} flip={flip} /></div>
    </PopIn>
  );
};

/** "NET WT" label like on the front of a pack. */
export const NetWt: React.FC<{text: string; size?: number; hot?: boolean}> = ({text, size = 44, hot}) => (
  <div style={{display: 'inline-flex', alignItems: 'baseline', gap: size * 0.3, background: hot ? '#FFE08A' : '#FFFFFF', border: `5px solid ${INK}`, borderRadius: 12, padding: `${size * 0.12}px ${size * 0.4}px`, fontFamily: SANS, color: INK, boxShadow: '0 6px 0 rgba(0,0,0,0.18)', whiteSpace: 'nowrap'}}>
    <span style={{fontWeight: 800, fontSize: size * 0.5, letterSpacing: 1}}>NET WT</span>
    <span style={{fontWeight: 900, fontSize: size}}>{text}</span>
  </div>
);

/** Old value -> new value. At `swapAt` the old one is struck through and the new one pops in coral. */
export const FromTo: React.FC<{from: string; to: string; unit?: string; at: number; swapAt: number; x: number; y: number; size?: number; label?: string}> = ({from, to, unit, at, swapAt, x, y, size = 120, label}) => {
  const f = useCurrentFrame();
  const strike = interpolate(f, [swapAt - 6, swapAt + 4], [0, 1], cl);
  return (
    <PopIn at={at} origin="0% 50%" style={{left: x, top: y}}>
      <div style={{...card(), padding: '22px 40px 26px', fontFamily: SANS, color: INK, minWidth: 560}}>
        {label && <div style={{fontWeight: 700, fontSize: 34, marginBottom: 6}}>{label}</div>}
        <div style={{display: 'flex', alignItems: 'center', gap: 28}}>
          <div style={{position: 'relative', fontWeight: 900, fontSize: size, lineHeight: 1, opacity: f >= swapAt ? 0.5 : 1}}>
            {from}
            <div style={{position: 'absolute', left: -8, top: '52%', height: size * 0.09, width: `calc(${strike * 100}% + 16px)`, background: '#E5484D', borderRadius: 8, transform: 'rotate(-6deg)'}} />
          </div>
          <PopIn at={swapAt} origin="0% 50%" style={{position: 'relative'}}>
            <div style={{display: 'flex', alignItems: 'center', gap: 22}}>
              <div style={{fontWeight: 900, fontSize: size * 0.6}}>→</div>
              <div style={{fontWeight: 900, fontSize: size, lineHeight: 1, color: '#E5484D'}}>{to}</div>
            </div>
          </PopIn>
        </div>
        {unit && <div style={{fontWeight: 700, fontSize: 36, marginTop: 8}}>{unit}</div>}
      </div>
    </PopIn>
  );
};

/** Horizontal bars that grow. `value` sets the length (relative to max); `show` is the printed number. */
export type BarRow = {label: string; value: number; show: string; color: string; at: number};
export const HBars: React.FC<{rows: BarRow[]; max: number; x: number; y: number; w?: number; barH?: number; gap?: number}> = ({rows, max, x, y, w = 980, barH = 96, gap = 70}) => {
  const f = useCurrentFrame();
  return (
    <div style={{position: 'absolute', left: x, top: y}}>
      {rows.map((r, i) => {
        const g = interpolate(f, [r.at, r.at + 20], [0, 1], cl);
        const len = Math.max(14, (r.value / max) * w * g);
        return (
          <div key={i} style={{marginBottom: gap, opacity: f < r.at ? 0 : 1}}>
            <div style={{fontFamily: SANS, fontWeight: 800, fontSize: 38, color: INK, marginBottom: 10}}>{r.label}</div>
            <div style={{display: 'flex', alignItems: 'center', gap: 24}}>
              <div style={{width: len, height: barH, background: r.color, border: `6px solid ${INK}`, borderRadius: 16, boxShadow: '0 8px 0 rgba(0,0,0,0.18)', boxSizing: 'border-box'}} />
              <div style={{fontFamily: SANS, fontWeight: 900, fontSize: barH * 0.8, color: INK, opacity: g}}>{r.show}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

/** Simple flags drawn in code: France (3 stripes), South Korea (simplified: white field + red/blue disc, no trigrams). */
export const Flag: React.FC<{kind: 'fr' | 'kr'; h?: number}> = ({kind, h = 200}) => {
  const w = h * 1.5;
  const frame: React.CSSProperties = {width: w, height: h, border: `7px solid ${INK}`, borderRadius: 14, overflow: 'hidden', boxShadow: '0 10px 0 rgba(0,0,0,0.2)', boxSizing: 'border-box', display: 'flex'};
  if (kind === 'fr') return <div style={frame}>{['#1F4E9E', '#FFFFFF', '#E5484D'].map((c) => <div key={c} style={{flex: 1, background: c}} />)}</div>;
  return (
    <div style={{...frame, background: '#fff', alignItems: 'center', justifyContent: 'center'}}>
      <div style={{width: h * 0.5, height: h * 0.5, borderRadius: '50%', background: 'linear-gradient(180deg, #D62E3B 50%, #1F4E9E 50%)', border: `4px solid ${INK}`, transform: 'rotate(-30deg)'}} />
    </div>
  );
};

/** Rubber stamp that slams in at `at` (pair with <Sfx name="stamp" />). */
export const Stamp: React.FC<{text: string; at: number; x: number; y: number; color?: string; size?: number; rot?: number}> = ({text, at, x, y, color = '#E5484D', size = 92, rot = -12}) => {
  const f = useCurrentFrame();
  if (f < at) return null;
  const s = interpolate(f, [at, at + 5, at + 9], [2.2, 0.94, 1], cl);
  return (
    <div style={{position: 'absolute', left: x, top: y, transform: `rotate(${rot}deg) scale(${s})`, opacity: interpolate(f, [at, at + 3], [0, 0.95], cl)}}>
      <div style={{border: `10px solid ${color}`, borderRadius: 18, padding: '8px 34px', fontFamily: SANS, fontWeight: 900, fontSize: size, color, letterSpacing: 4, whiteSpace: 'nowrap', background: 'rgba(255,255,255,0.65)'}}>{text}</div>
    </div>
  );
};

/** Supermarket shelf tag: big shelf price + small unit-price strip. `hiAt` highlights the unit price. */
export const ShelfTag: React.FC<{price: string; unit: string; per?: string; at: number; x: number; y: number; scale?: number; hiAt?: number; frozen?: boolean; unitColor?: string}> = ({price, unit, per = 'per oz', at, x, y, scale = 1, hiAt, frozen, unitColor}) => {
  const f = useCurrentFrame();
  const hi = hiAt !== undefined && f >= hiAt;
  const pulse = hi ? 1 + 0.05 * Math.max(0, Math.sin(((f - hiAt!) / 12) * Math.PI)) * interpolate(f, [hiAt!, hiAt! + 36], [1, 0], cl) : 1;
  return (
    <PopIn at={at} origin="50% 50%" style={{left: x, top: y}}>
      <div style={{transform: `scale(${scale})`, transformOrigin: '0 0', width: 620, ...card('#FFFFFF'), overflow: 'hidden', fontFamily: SANS, color: INK}}>
        <div style={{background: frozen ? '#BFE6FF' : '#FFFFFF', padding: '20px 34px 12px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end'}}>
          <div style={{width: 150, height: 26, borderRadius: 6, background: 'rgba(0,0,0,0.12)', marginBottom: 20}} />
          <div style={{fontWeight: 900, fontSize: 130, lineHeight: 1, color: frozen ? '#1F4E9E' : INK}}>{price}</div>
        </div>
        <div style={{background: hi ? '#FFD23F' : '#F1EADF', borderTop: `5px solid ${INK}`, padding: '12px 34px', display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', transform: `scale(${pulse})`, transformOrigin: '50% 50%'}}>
          <span style={{fontWeight: 700, fontSize: 30}}>unit price</span>
          <span style={{fontWeight: 900, fontSize: hi ? 58 : 40, color: unitColor ?? INK}}>{unit} <span style={{fontSize: 28, fontWeight: 700}}>{per}</span></span>
        </div>
      </div>
    </PopIn>
  );
};

/** Round "this product shrank" sticker (generic, like the French shelf notice). */
