/** Magnifying glass (detective). */
export const Magnifier: React.FC<{size?: number}> = ({size = 260}) => (
  <div style={{position: 'relative', width: size, height: size}}>
    <div style={{position: 'absolute', left: 0, top: 0, width: size * 0.7, height: size * 0.7, borderRadius: '50%', border: `${size * 0.07}px solid ${INK}`, background: 'rgba(191,230,255,0.55)', boxSizing: 'border-box'}} />
    <div style={{position: 'absolute', left: size * 0.58, top: size * 0.6, width: size * 0.46, height: size * 0.13, background: '#8A5A2B', border: `5px solid ${INK}`, borderRadius: 12, transform: 'rotate(45deg)', transformOrigin: '0 50%'}} />
  </div>
);

/** Big handwritten word with a coloured swipe behind it. */
export const WordSwipe: React.FC<{text: string; at: number; x: number; y: number; size?: number; color?: string}> = ({text, at, x, y, size = 110, color = '#FFD23F'}) => {
  const f = useCurrentFrame();
  const sw = interpolate(f, [at + 4, at + 16], [0, 1], cl);
  return (
    <PopIn at={at} origin="0% 50%" style={{left: x, top: y}}>
      <div style={{position: 'relative', display: 'inline-block'}}>
        <div style={{position: 'absolute', left: -14, right: -14, bottom: size * 0.08, height: size * 0.42, background: color, borderRadius: 10, transform: `scaleX(${sw})`, transformOrigin: '0 50%'}} />
        <div style={{position: 'relative', fontFamily: HAND, fontWeight: 700, fontSize: size, color: INK, whiteSpace: 'nowrap'}}>{text}</div>
      </div>
    </PopIn>
  );
};

/** Calculator screen for <Phone>: price / size = unit price. */
export const CalcScreen: React.FC<{at: number}> = ({at}) => {
  const f = useCurrentFrame();
  const line = (i: number) => ({opacity: interpolate(f, [at + i * 14, at + i * 14 + 8], [0, 1], cl)});
  return (
    <div style={{padding: '34px 22px', display: 'flex', flexDirection: 'column', gap: 14, fontFamily: SANS, color: INK, textAlign: 'right'}}>
      <div style={{fontSize: 24, fontWeight: 700, opacity: 0.6, textAlign: 'left'}}>Calculator</div>
      <div style={{fontSize: 46, fontWeight: 800, ...line(0)}}>$4.00</div>
      <div style={{fontSize: 46, fontWeight: 800, ...line(1)}}>÷ 14 oz</div>
      <div style={{height: 5, background: INK, ...line(2)}} />
      <div style={{fontSize: 58, fontWeight: 900, color: '#E5484D', ...line(2)}}>$0.29</div>
      <div style={{fontSize: 28, fontWeight: 700, ...line(2)}}>per oz</div>
    </div>
  );
};

/** Static price tag (same look as PriceTag) for carried objects. */
export const TagNode: React.FC<{text: string; size?: number; color?: string; rot?: number}> = ({text, size = 120, color = '#FF6B6B', rot = -6}) => (
  <div style={{transform: `rotate(${rot}deg)`, display: 'flex', alignItems: 'center', background: color, border: `7px solid ${INK}`, borderRadius: '24px 70px 70px 24px', padding: `${size * 0.12}px ${size * 0.4}px ${size * 0.12}px ${size * 0.25}px`, fontFamily: SANS, fontWeight: 900, fontSize: size, color: '#fff', boxShadow: '0 10px 0 rgba(0,0,0,0.2)', whiteSpace: 'nowrap'}}>
    <div style={{width: size * 0.22, height: size * 0.22, borderRadius: '50%', background: '#fff', border: `5px solid ${INK}`, marginRight: size * 0.2}} />
    {text}
  </div>
);

/** Big exact number (decimals allowed) on a card. */
export const BigNum: React.FC<{text: string; label: string; at: number; x: number; y: number; w?: number; color?: string}> = ({text, label, at, x, y, w = 640, color = INK}) => (
  <PopIn at={at} origin="50% 50%" style={{left: x, top: y}}>
    <div style={{width: w, ...card(), padding: '26px 30px', textAlign: 'center', fontFamily: SANS, color: INK}}>
      <div style={{fontWeight: 900, fontSize: 150, lineHeight: 1, color}}>{text}</div>
      <div style={{fontWeight: 700, fontSize: 38, marginTop: 10}}>{label}</div>
    </div>
  </PopIn>
);

/** Prop placed at absolute coordinates; at < 0 = already there (no pop, e.g. after a swap or a carry handoff). */
export const P: React.FC<{name: string; x: number; y: number; h?: number; w?: number; at?: number; flip?: boolean}> = ({name, x, y, h, w, at = -30, flip}) => (
  <PopIn at={at} style={{left: x, top: y}}><Prop name={name} h={h} w={w} flip={flip} /></PopIn>
);

/** Anything placed by its CENTER (cx, cy) with a pop; used for carried objects so the carry lands exactly on it. */
export const Centered: React.FC<{x: number; y: number; at?: number; children: React.ReactNode}> = ({x, y, at = -30, children}) => (
  <PopIn at={at} origin="0 0" style={{left: x, top: y}}><div style={{transform: 'translate(-50%, -50%)'}}>{children}</div></PopIn>
);

export {CountUp};
